package com.cosmetic.shopbackend.catalog;
import com.cosmetic.shopbackend.brand.BrandRepository; import com.cosmetic.shopbackend.brand.BrandStatus; import com.cosmetic.shopbackend.identity.AccountRole; import com.cosmetic.shopbackend.security.ShopPrincipal; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.*;
@RestController @RequestMapping("/api/products")
public class CatalogController {
 private final ProductRepository products; private final ProductVariantRepository variants; private final BrandRepository brands;
 public CatalogController(ProductRepository p,ProductVariantRepository v,BrandRepository b){products=p;variants=v;brands=b;}
 @GetMapping public List<Product> list(){return products.findByStatus(Product.Status.ACTIVE).stream().filter(p->brands.findById(p.getBrandId()).map(b->b.getStatus()==BrandStatus.ACTIVE).orElse(false)).toList();}
 @GetMapping("/{id}") public ResponseEntity<?> get(@PathVariable String id){return products.findById(id).filter(p->p.getStatus()==Product.Status.ACTIVE).filter(p->brands.findById(p.getBrandId()).map(b->b.getStatus()==BrandStatus.ACTIVE).orElse(false)).map(p->Map.of("product",p,"variants",variants.findByProductId(id).stream().filter(v->v.getStatus()==ProductVariant.Status.ACTIVE).toList())).map(ResponseEntity::ok).orElseGet(()->ResponseEntity.notFound().build());}
 public record ProductRequest(String brandId,String categoryId,String name,String primaryImageUrl){}
 @PostMapping public ResponseEntity<Product> create(@AuthenticationPrincipal ShopPrincipal actor,@RequestBody ProductRequest r){
  if(actor==null||actor.role()!=AccountRole.SELLER||r.brandId()==null||r.brandId().isBlank()||r.categoryId()==null||r.categoryId().isBlank()||r.name()==null||r.name().isBlank()||brands.findByIdAndSeller_Id(r.brandId(),actor.accountId()).isEmpty()) throw new ResponseStatusException(HttpStatus.FORBIDDEN);
  Product p=new Product(UUID.randomUUID().toString(),r.brandId(),r.categoryId(),r.name()); p.update(r.name(),r.categoryId(),r.primaryImageUrl()); return ResponseEntity.status(HttpStatus.CREATED).body(products.save(p)); }
 @PutMapping("/{id}") public ResponseEntity<?> update(@AuthenticationPrincipal ShopPrincipal actor,@PathVariable String id,@RequestBody ProductRequest r){return products.findById(id).filter(p->actor!=null&&actor.role()==AccountRole.SELLER&&brands.findByIdAndSeller_Id(p.getBrandId(),actor.accountId()).isPresent()).map(p->{p.update(r.name(),r.categoryId(),r.primaryImageUrl());return ResponseEntity.ok(products.save(p));}).orElseGet(()->ResponseEntity.status(HttpStatus.FORBIDDEN).build());}
 @PatchMapping("/{id}/status") public ResponseEntity<?> status(@AuthenticationPrincipal ShopPrincipal actor,@PathVariable String id,@RequestParam Product.Status value){return products.findById(id).filter(p->actor!=null&&actor.role()==AccountRole.SELLER&&brands.findByIdAndSeller_Id(p.getBrandId(),actor.accountId()).isPresent()).map(p->{p.status(value);return ResponseEntity.ok(products.save(p));}).orElseGet(()->ResponseEntity.status(HttpStatus.FORBIDDEN).build());}
}
